//! D805-1 + D805-2 (round 76, lane A) — the DG **face terms** of
//! `dg_elasticity.rs` and `dg_advection.rs` must be entry-by-entry equal to
//! MFEM 4.10's.
//!
//! # The two debts
//!
//! **D805-1** — `DgElasticityAssembler`'s penalty was `kappa·ipw·(λ+2μ)` with
//! the **averaged** Lamé constants; MFEM's `DGElasticityIntegrator` uses
//! `jmatcoef = kappa·(nor·nor)·wLM` with
//! `wLM = (ipw/2)·((λ₁+2μ₁)/W₁ + (λ₂+2μ₂)/W₂)` on an interior face and
//! `wLM = ipw·(λ+2μ)/W` on a boundary one (`w = ip.weight` is *not* halved
//! there).  Two things were wrong: the per-element `/Weight()` (MFEM weights
//! the penalty by the element measure, not by `1/|nor|`) and the fact that the
//! factor belongs to `|nor|²` with the bare `ipw` rather than to `w_f`.  On a
//! straight uniform square mesh `|nor|²/Weight == 1` and the averaged interior
//! coefficient coincides, which is why only curved or non-square elements show
//! it: 41.5% on the fixture below.
//!
//! **D805-2** — `DGAdvectionIntegrator`'s face term was the *conservative*
//! upwind form `−∫⟦v⟧F̂`.  That is not entry-by-entry equal to any MFEM
//! integrator: MFEM's `NonconservativeDGTraceIntegrator(velocity, α)` places
//! the one-sided contributions in the `(1,1)/(1,2)` (inflow) and
//! `(2,1)/(2,2)` (outflow) blocks, so the pre-fix matrix had a different
//! sparsity (48 of 256 entries wrong on the fixture below).
//!
//! # Gold
//!
//! `tmp/d805r76/d805r76_probe.cpp` (MFEM 4.10 static lib) dumps every matrix
//! below on the same fixture in the same DOF order; the strings at the bottom
//! of this file are its `[MAT*]` rows verbatim (17 significant digits), with
//! the vector-valued elasticity matrices mapped from MFEM's element-local
//! `comp*ndofs + dof` layout to fem-rs' `dof*dim + comp`.  Regenerate the whole
//! comparison with
//! `wsl -e bash -lc 'cd /home/quan/work/d805r76 && ./probe -o 1 -s -1 -k 4'`
//! plus `tmp/d805r76/cmp2.py`; the fixture's element and DOF numbering is
//! pinned against MFEM by `d805_d799_3_dg_face_geometry.rs`, and re-verified
//! (`tmp/d805r76/probe_conn.cpp`).
//!
//! # Fixture
//!
//! The D795/D799-3 fixture: 2×2 quadrilaterals on `[0,1]²`, `SetCurvature(3)`
//! (order-3 geometry, so `Trans.OrderW() == 5`), then the smooth bend
//! `(X,Y) ↦ (X(1+0.15Y(1−Y)), Y+0.15XY(1−Y))`; order-1 L2 space, λ = μ = 1,
//! `sigma = −1`, `kappa = 4`, every boundary attribute marked Dirichlet.
//!
//! # Quadrature rules (MFEM's own, one per integrator — not one per face)
//!
//! * `DGDiffusionIntegrator`: volume `p+p+dim−1 = 3` → 2×2 and face
//!   `2·max(o₁,o₂) = 2` → 2 points (what `DgAssembler::assemble_dg` receives).
//! * `ElasticityIntegrator` volume: `2·Trans.OrderGrad(&el) = 6` → 4×4, derived
//!   internally by `assemble_sip_elasticity` (D805-1).
//! * `DGElasticityIntegrator` faces: `2·max(o₁,o₂) = 2` → 2 points (the
//!   `quad_order` argument).
//! * `DGTraceIntegrator` faces: `min(OrderW₁,OrderW₂) + 2·max(o₁,o₂)`
//!   `+ (Pk ? 1 : 0) = 5 + 2 = 7` → 4 points.

use fem_assembly::dg::dg_advection::{assemble_dg_interior_faces, DGAdvectionIntegrator};
use fem_assembly::dg::dg_elasticity::DgElasticityAssembler;
use fem_assembly::dg::dg_trace::DgTraceIntegrator;
use fem_assembly::postproc::coefficient::ConstantVectorCoeff;
use fem_assembly::standard::DiffusionIntegrator;
use fem_assembly::{Assembler, DgAssembler, InteriorFaceList};
use fem_mesh::{ElementType, Mesh, MeshTopology};
use fem_space::L2Space;

/// Entry-by-entry relative tolerance: both codes sum the same products in a
/// different order, so ~1e-13 is the recoverable limit for a well-scaled entry.
const RTOL: f64 = 1e-12;
/// Absolute floor, as a multiple of the matrix magnitude `max|A|`: every entry
/// is a sum of `O(max|A|)`-sized products accumulated in a different order on the
/// two sides, so it cannot agree better than a few `ulp(max|A|)`; the honest
/// entry-by-entry bound is therefore `|a−b| ≤ RTOL·|b| + ATOL_REL·max|A|`.
///
/// `ATOL_REL = 1e-14` is ~45 ulp of a magnitude-7 matrix, a comfortable margin
/// over the measured worst (20.1 ulp, `ELBDZ`).  The measured worst
/// absolute deviations over all ten matrices are 3.7e-14 at `max|A| = 19`
/// (`ELBD`, 2 ulp), 2.8e-14 at `max|A| = 6.3` (`ELBDZ`, 4.5 ulp) and 5.3e-15 at
/// `max|A| = 6.8` (`ELAV`, 0.8 ulp) — see the `tmp/d805r76/after_table.txt`
/// `abs/ulp` columns.  The *teeth* are three orders of magnitude outside this
/// band: the pre-fix penalty was off by 41.5% (1.0e-1 absolute) and the pre-fix
/// advection block layout by 4.7e-3 absolute.
const ATOL_REL: f64 = 1e-14;

/// Every boundary attribute of the fixture is marked Dirichlet (the probe marks
/// `dir_bdr` on all attributes, so the tag *numbering* does not matter).
const EL_BDR_ATTRS: [i32; 4] = [1, 2, 3, 4];

fn rel(a: f64, b: f64) -> f64 {
    let d = (a - b).abs();
    let s = a.abs().max(b.abs());
    if s < 1e-12 {
        d
    } else {
        d / s
    }
}

/// The D795 curved fixture, identical to `d805_d799_3_dg_face_geometry.rs`.
fn build_mesh(curved: bool) -> Mesh<2> {
    let mut c = Vec::new();
    for j in 0..3 {
        for i in 0..3 {
            c.push(i as f64 * 0.5);
            c.push(j as f64 * 0.5);
        }
    }
    let e: Vec<u32> = vec![0, 1, 4, 3, 3, 4, 7, 6, 4, 5, 8, 7, 1, 2, 5, 4];
    let bn: Vec<u32> = vec![0, 1, 1, 2, 7, 6, 8, 7, 3, 0, 6, 3, 2, 5, 5, 8];
    let bt: Vec<i32> = vec![1, 1, 3, 3, 4, 4, 2, 2];
    let mut m = Mesh::<2>::uniform(
        c,
        e,
        vec![1; 4],
        ElementType::Quad4,
        bn,
        bt,
        ElementType::Line2,
    );
    if curved {
        m.set_curvature(3);
        m.transform(|[x, y]| {
            [x * (1.0 + 0.15 * y * (1.0 - y)), y + 0.15 * x * y * (1.0 - y)]
        });
    }
    m
}

fn dense(mat: &fem_linalg::CsrMatrix<f64>) -> Vec<Vec<f64>> {
    let n = mat.nrows;
    let mut out = vec![vec![0.0; n]; n];
    for i in 0..n {
        for k in mat.row_ptr[i]..mat.row_ptr[i + 1] {
            out[i][mat.col_idx[k] as usize] = mat.values[k];
        }
    }
    out
}

fn sub(a: &[Vec<f64>], b: &[Vec<f64>]) -> Vec<Vec<f64>> {
    (0..a.len())
        .map(|i| (0..a[i].len()).map(|j| a[i][j] - b[i][j]).collect())
        .collect()
}

/// Every matrix the comparator checks, in the fem-rs DOF layout (`byNODES` for
/// the vector-valued elasticity space).
///
/// `adv_qo` is the `DGTraceIntegrator` face rule (MFEM's default is 7 here),
/// `ela_qo` the `DGElasticityIntegrator` face rule (MFEM's default is 2).
fn assemble_all(adv_qo: u8, ela_qo: u8) -> Vec<(&'static str, Vec<Vec<f64>>)> {
    let m = build_mesh(true);
    let space = L2Space::new(m.clone(), 1);
    let ifl = InteriorFaceList::build(&m);
    let n_elem = m.n_elements();
    let lam = vec![1.0; n_elem];
    let mu = vec![1.0; n_elem];
    let empty = InteriorFaceList { faces: Vec::new() };
    let mut out: Vec<(&'static str, Vec<Vec<f64>>)> = Vec::new();

    // ── DIF / DIFIF: the `dg.rs` DGDiffusion control (already 1e-13) ────────
    let dif = dense(&DgAssembler::assemble_dg(&space, &ifl, 1.0, -1.0, 4.0, 2, Some(&[])));
    let vol_dif = dense(&Assembler::assemble_bilinear(
        &space,
        &[&DiffusionIntegrator { kappa: 1.0 }],
        2,
    ));
    out.push(("DIF", dif.clone()));
    out.push(("DIFIF", sub(&dif, &vol_dif)));

    // ── ADV / ADV2: MFEM's NonconservativeDGTrace(vel, -1) and the raw
    // DGTrace(vel, -1, 0.5) that it is the transpose of ────────────────────
    let dg_adv = DGAdvectionIntegrator {
        velocity: ConstantVectorCoeff(vec![1.0, 0.0]),
        alpha: -1.0,
    };
    let mut coo = fem_linalg::CooMatrix::<f64>::new(space.n_dofs(), space.n_dofs());
    assemble_dg_interior_faces(&mut coo, &m, &space, &ifl, 1, adv_qo, &dg_adv);
    out.push(("ADV", dense(&coo.into_csr())));

    let mut coo2 = fem_linalg::CooMatrix::<f64>::new(space.n_dofs(), space.n_dofs());
    let dgt = DgTraceIntegrator::new(ConstantVectorCoeff(vec![1.0, 0.0]), -1.0, 0.5);
    assemble_dg_interior_faces(&mut coo2, &m, &space, &ifl, 1, adv_qo, &dgt);
    out.push(("ADV2", dense(&coo2.into_csr())));

    // ── ELA/ELAV/ELZ/ELZV: DGElasticityIntegrator ± the interior faces ─────
    let ela = DgElasticityAssembler::assemble_sip_elasticity(
        &space, &ifl, &lam, &mu, 4.0, -1.0, 2, ela_qo, &[]);
    let elav = DgElasticityAssembler::assemble_sip_elasticity(
        &space, &empty, &lam, &mu, 4.0, -1.0, 2, ela_qo, &[]);
    let elz = DgElasticityAssembler::assemble_sip_elasticity(
        &space, &ifl, &lam, &mu, 0.0, -1.0, 2, ela_qo, &[]);
    let elzv = DgElasticityAssembler::assemble_sip_elasticity(
        &space, &empty, &lam, &mu, 0.0, -1.0, 2, ela_qo, &[]);
    out.push(("ELA", dense(&ela)));
    out.push(("ELAV", dense(&elav)));
    out.push(("ELZ", dense(&elz)));
    out.push(("ELZV", dense(&elzv)));

    // ── ELBD/ELBDZ: the weak-Dirichlet **boundary** face term ─────────────
    let elbd = DgElasticityAssembler::assemble_sip_elasticity(
        &space, &empty, &lam, &mu, 4.0, -1.0, 2, ela_qo, &EL_BDR_ATTRS);
    let elbdz = DgElasticityAssembler::assemble_sip_elasticity(
        &space, &empty, &lam, &mu, 0.0, -1.0, 2, ela_qo, &EL_BDR_ATTRS);
    out.push(("ELBD", dense(&elbd)));
    out.push(("ELBDZ", dense(&elbdz)));
    out
}

fn find<'a>(all: &'a [(&'static str, Vec<Vec<f64>>)], tag: &str) -> &'a [Vec<f64>] {
    &all.iter().find(|(t, _)| *t == tag).expect("tag present").1
}

fn gold_for(tag: &str) -> &'static str {
    match tag {
        "DIF" => MFEM_MATDIF,
        "DIFIF" => MFEM_MATDIFIF,
        "ADV" => MFEM_MATADV,
        "ADV2" => MFEM_MATADV2,
        "ELA" => MFEM_MATELA,
        "ELAV" => MFEM_MATELAV,
        "ELZ" => MFEM_MATELZ,
        "ELZV" => MFEM_MATELZV,
        "ELBD" => MFEM_MATELBD,
        "ELBDZ" => MFEM_MATELBDZ,
        other => panic!("no gold for {other}"),
    }
}

/// `max|A|` of a gold string.
fn mat_max(gold: &str) -> f64 {
    parse_mat(gold)
        .iter()
        .flat_map(|r| r.iter())
        .fold(0.0_f64, |m, v| m.max(v.abs()))
}

fn parse_mat(s: &str) -> Vec<Vec<f64>> {
    s.lines()
        .filter(|l| !l.trim().is_empty())
        .map(|l| {
            l.split_whitespace()
                .map(|v| v.parse::<f64>().expect("17-digit gold value"))
                .collect()
        })
        .collect()
}

/// Serialise a matrix into the gold-string format (used for the derived
/// `*_FACE` checks, whose gold is the difference of two golds).
fn join_mat(m: &[Vec<f64>]) -> String {
    let mut s = String::new();
    for row in m {
        for v in row {
            s.push_str(&format!("{v:.17e} "));
        }
        s.push('\n');
    }
    s
}

/// Compare one matrix against its gold string, returning the worst relative
/// deviation; asserts entry-by-entry agreement inside `RTOL` plus the
/// `ATOL_REL * scale` absolute floor.
///
/// `scale` is the magnitude of the **sums whose cancellation produced the
/// entries**: the matrix's own `max|A|` for a directly assembled matrix, but the
/// `max|A|` of the *operands* for a derived difference (a matrix of magnitude 24
/// and one of magnitude 6 are each only accurate to ~1e-15*24, so their
/// difference carries that much absolute error even when it is 1e-2 in size).
fn check_entry_by_entry(
    tag: &str,
    got: &[Vec<f64>],
    gold: &str,
    scale: f64,
) -> Result<f64, String> {
    let want = parse_mat(gold);
    assert_eq!(got.len(), want.len(), "{tag}: {} rows vs gold {}", got.len(), want.len());
    let mut worst = 0.0_f64;
    let mut worst_at = (0usize, 0usize);
    let mut nbad = 0usize;
    let mut n = 0usize;
    for i in 0..want.len() {
        assert_eq!(got[i].len(), want[i].len(), "{tag}: row {i} width");
        for j in 0..want[i].len() {
            n += 1;
            let (a, b) = (got[i][j], want[i][j]);
            let excess = (a - b).abs() - (RTOL * b.abs() + ATOL_REL * scale);
            if excess > 0.0 {
                nbad += 1;
            }
            if excess > worst {
                worst = excess;
                worst_at = (i, j);
            }
        }
    }
    let verdict = if nbad == 0 {
        Ok(())
    } else {
        Err(format!(
            "{tag}: {nbad} of {n} entries outside tolerance (|A|_max = {scale:.3e}), worst excess              {worst:.3e} at {worst_at:?}; fem-rs {:e} vs MFEM {:e}",
            got[worst_at.0][worst_at.1], want[worst_at.0][worst_at.1]
        ))
    };
    // Worst *relative* deviation and the worst absolute deviation normalised by
    // `max|A|`, for the log line only.
    let mut rel_worst = 0.0_f64;
    let mut abs_worst = 0.0_f64;
    let mut n_rel_1e12 = 0usize;
    for i in 0..want.len() {
        for j in 0..want[i].len() {
            let r = rel(got[i][j], want[i][j]);
            if r > RTOL {
                n_rel_1e12 += 1;
            }
            rel_worst = rel_worst.max(r);
            abs_worst = abs_worst.max((got[i][j] - want[i][j]).abs());
        }
    }
    eprintln!(
        "  {tag:<12} max|A|={scale:.4e} max_rel={rel_worst:.3e}          max_abs/ulp(max|A|)={:.2} entries>1e-12={n_rel_1e12}/{n}",
        abs_worst / (scale * f64::EPSILON)
    );
    verdict.map(|()| rel_worst)
}

/// D805-1 + D805-2: every system assembled from the DG face terms is
/// entry-by-entry MFEM's, at MFEM's own quadrature rules, including the derived
/// face-only parts (which cancel the volume term and so isolate the face
/// terms).
#[test]
fn dg_face_terms_are_entry_by_entry_mfem() {
    let all = assemble_all(7, 2);
    let mut failures: Vec<String> = Vec::new();

    for (tag, got) in &all {
        if let Err(msg) = check_entry_by_entry(tag, got, gold_for(tag), mat_max(gold_for(tag))) {
            failures.push(msg);
        }
    }
    // Derived: the pure face parts (MFEM gold differences).
    for (num, base, face_tag) in [
        ("ELA", "ELAV", "ELA_FACE"),
        ("ELZ", "ELZV", "ELZ_FACE"),
        ("ELBD", "ELAV", "ELBDR_FACE"),
        ("ELBDZ", "ELZV", "ELBDRZ_FACE"),
    ] {
        let g_n = parse_mat(gold_for(num));
        let g_b = parse_mat(gold_for(base));
        let op_scale = mat_max(gold_for(num)).max(mat_max(gold_for(base)));
        if let Err(msg) = check_entry_by_entry(
            face_tag,
            &sub(find(&all, num), find(&all, base)),
            &join_mat(&sub(&g_n, &g_b)),
            op_scale,
        ) {
            failures.push(msg);
        }
    }
    assert!(
        failures.is_empty(),
        "D805-1/D805-2: {} of 14 comparisons are not entry-by-entry MFEM:
  {}",
        failures.len(),
        failures.join("
  ")
    );
}

/// Dump every matrix in the `[RS_MAT*]` format of `tmp/d805r76/cmp2.py`.
///
/// Run with
/// `D805R76_DUMP=1 cargo test --release -p fem-assembly --test
/// d805r76_dg_face_mfem_equivalence dg_face_terms_dump -- --nocapture`,
/// optionally with `D805R76_ADV_QO` / `D805R76_ELA_QO` to pin the face rules
/// (the defaults are MFEM's 7 and 2).
#[test]
fn dg_face_terms_dump() {
    if std::env::var("D805R76_DUMP").is_err() {
        return;
    }
    let adv: u8 = std::env::var("D805R76_ADV_QO")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(7);
    let ela: u8 = std::env::var("D805R76_ELA_QO")
        .ok()
        .and_then(|v| v.parse().ok())
        .unwrap_or(2);
    println!("# D805R76_ADV_QO={adv} D805R76_ELA_QO={ela}");
    for (tag, m) in assemble_all(adv, ela) {
        println!("[RS_MAT{tag}] n={}", m.len());
        for row in &m {
            print!("   ");
            for v in row {
                print!(" {v:.17e}");
            }
            println!();
        }
    }
}

